package tink

import (
	"bytes"
	"context"
	"crypto/mlkem"
	"errors"
	"flag"
	"io"
	"math/rand/v2"
	"os"
	"path/filepath"
	"sync"
	"testing"

	"github.com/jdillenkofer/pithos/internal/storage/database"
	"github.com/jdillenkofer/pithos/internal/storage/metadatapart/partstore"
	testutils "github.com/jdillenkofer/pithos/internal/testing"
	"github.com/stretchr/testify/require"
)

// The fixtures were written by the google/tink/go based implementation. They
// must never be regenerated by a newer implementation, otherwise the test no
// longer proves that existing parts stay readable.
var updateLegacyFixtures = flag.Bool("update-legacy-fixtures", false, "rewrite the legacy Tink part fixtures in testdata")

const legacyFixturePassword = "legacy-fixture-password"

var legacyFixturePartId = partstore.MustNewPartIdFromString("01JBQ6Z8Y3K4N5P6Q7R8S9T0VW")

type memoryPartStore struct {
	mu    sync.Mutex
	parts map[partstore.PartId][]byte
}

func newMemoryPartStore() *memoryPartStore {
	return &memoryPartStore{parts: map[partstore.PartId][]byte{}}
}

func (m *memoryPartStore) Start(ctx context.Context) error { return nil }
func (m *memoryPartStore) Stop(ctx context.Context) error  { return nil }
func (m *memoryPartStore) PutPart(ctx context.Context, tx database.Tx, partId partstore.PartId, reader io.Reader) error {
	data, err := io.ReadAll(reader)
	if err != nil {
		return err
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	m.parts[partId] = data
	return nil
}
func (m *memoryPartStore) GetPart(ctx context.Context, tx database.Tx, partId partstore.PartId) (io.ReadCloser, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	data, ok := m.parts[partId]
	if !ok {
		return nil, errors.New("part not found")
	}
	return io.NopCloser(bytes.NewReader(data)), nil
}
func (m *memoryPartStore) GetPartIds(ctx context.Context, tx database.Tx) ([]partstore.PartId, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	partIds := make([]partstore.PartId, 0, len(m.parts))
	for partId := range m.parts {
		partIds = append(partIds, partId)
	}
	return partIds, nil
}
func (m *memoryPartStore) DeletePart(ctx context.Context, tx database.Tx, partId partstore.PartId) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	delete(m.parts, partId)
	return nil
}

// legacyFixturePlaintext spans one full segment and a partial second one.
func legacyFixturePlaintext() []byte {
	plaintext := make([]byte, DefaultSegmentSize+12*1024)
	_, _ = rand.NewChaCha8([32]byte{'p', 'i', 't', 'h', 'o', 's'}).Read(plaintext)
	return plaintext
}

func legacyFixtureMLKEMKey(t *testing.T) *mlkem.DecapsulationKey1024 {
	seed := make([]byte, mlkem.SeedSize)
	for i := range seed {
		seed[i] = byte(i)
	}
	key, err := mlkem.NewDecapsulationKey1024(seed)
	require.NoError(t, err)
	return key
}

func TestDecryptsPartsWrittenByLegacyTink(t *testing.T) {
	testutils.SkipIfIntegration(t)

	testCases := []struct {
		name     string
		fixture  string
		mlkemKey func(t *testing.T) *mlkem.DecapsulationKey1024
	}{
		{name: "LocalKMS", fixture: "legacy_local_kms.bin"},
		{name: "LocalKMSWithMLKEM", fixture: "legacy_local_kms_mlkem.bin", mlkemKey: legacyFixtureMLKEMKey},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			var mlkemKey *mlkem.DecapsulationKey1024
			if tc.mlkemKey != nil {
				mlkemKey = tc.mlkemKey(t)
			}
			innerStore := newMemoryPartStore()
			mw, err := NewWithLocalKMS(legacyFixturePassword, innerStore, mlkemKey)
			require.NoError(t, err)

			plaintext := legacyFixturePlaintext()
			fixturePath := filepath.Join("testdata", tc.fixture)
			if *updateLegacyFixtures {
				require.NoError(t, mw.PutPart(t.Context(), nil, *legacyFixturePartId, bytes.NewReader(plaintext)))
				require.NoError(t, os.MkdirAll("testdata", 0o755))
				require.NoError(t, os.WriteFile(fixturePath, innerStore.parts[*legacyFixturePartId], 0o644))
			}

			ciphertext, err := os.ReadFile(fixturePath)
			require.NoError(t, err)
			innerStore.parts[*legacyFixturePartId] = ciphertext

			rc, err := mw.GetPart(t.Context(), nil, *legacyFixturePartId)
			require.NoError(t, err)
			defer rc.Close()
			decrypted, err := io.ReadAll(rc)
			require.NoError(t, err)
			require.Equal(t, plaintext, decrypted)
		})
	}
}
